#!/usr/bin/env python3
"""IPv6 staged-trie compiler and lookup."""
import sys, os, json, re, math, array, ctypes, subprocess, tempfile, shutil

class Invalid(Exception):
    pass

# ---------- IPv6 ----------
_HEX = frozenset('0123456789abcdefABCDEF')
_DIG = frozenset('0123456789')

def parse_addr(s):
    if type(s) is not str:
        raise Invalid()
    if '::' in s:
        if s.count('::') != 1:
            raise Invalid()
        left, right = s.split('::')
        if left:
            lg = left.split(':')
            if not lg or any(g == '' for g in lg):
                raise Invalid()
        else:
            lg = []
        if right:
            rg = right.split(':')
            if not rg or any(g == '' for g in rg):
                raise Invalid()
        else:
            rg = []
        if len(lg) + len(rg) > 7:
            raise Invalid()
        groups = lg + ['0'] * (8 - len(lg) - len(rg)) + rg
    else:
        groups = s.split(':')
        if len(groups) != 8 or any(g == '' for g in groups):
            raise Invalid()
    val = 0
    for g in groups:
        if len(g) > 4:
            raise Invalid()
        for ch in g:
            if ch not in _HEX:
                raise Invalid()
        val = (val << 16) | int(g, 16)
    return val
