def fmt_addr(v):
    groups = [(v >> (112 - 16*i)) & 0xFFFF for i in range(8)]
    # longest run of >=2 zeros, leftmost
    bs = -1; bl = 0
    i = 0
    while i < 8:
        if groups[i] == 0:
            j = i
            while j < 8 and groups[j] == 0:
                j += 1
            if j - i >= 2 and j - i > bl:
                bl = j - i; bs = i
            i = j
        else:
            i += 1
    if bs >= 0:
        left = [format(g, 'x') for g in groups[:bs]]
        right = [format(g, 'x') for g in groups[bs+bl:]]
        return ':'.join(left) + '::' + ':'.join(right)
    return ':'.join(format(g, 'x') for g in groups)
```
