def parse_prefix(s):
    if type(s) is not str:
        raise Invalid()
    if s.count('/') != 1:
        raise Invalid()
    a, l = s.split('/')
    if not l or len(l) > 3:
        raise Invalid()
    for ch in l:
        if ch not in _DIG:
            raise Invalid()
    if len(l) > 1 and l[0] == '0':
        raise Invalid()
    L = int(l)
    if L > 128:
        raise Invalid()
    v = parse_addr(a)
    if v & ((1 << (128 - L)) - 1):
        raise Invalid()
    return v, L
