class Invalid(Exception):
    """Raised whenever a request (or image) violates the contract."""


# --------------------------------------------------------------------------
# IPv6 address / prefix parsing and canonical formatting
# --------------------------------------------------------------------------

_HEX = frozenset('0123456789abcdefABCDEF')
_DIG = frozenset('0123456789')


def parse_addr(s):
    """Parse a pure hexadecimal IPv6 address string into a 128-bit int."""
    if type(s) is not str:
        raise Invalid()
    if '::' in s:
        if s.count('::') != 1:
            raise Invalid()
        left, right = s.split('::')
        lg = left.split(':') if left else []
        rg = right.split(':') if right else []
        if any(g == '' for g in lg) or any(g == '' for g in rg):
            raise Invalid()
        if len(lg) + len(rg) > 7:
            raise Invalid()
        groups = lg + ['0'] * (8 - len(lg) - len(rg)) + rg
    else:
        groups = s.split(':')
        if len(groups) != 8 or any(g == '' for g in groups):
            raise Invalid()
    val = 0
    for g in groups:
        if len(g) > 4:
            raise Invalid()
        for ch in g:
            if ch not in _HEX:
                raise Invalid()
        val = (val << 16) | int(g, 16)
    return val
