    dstart[1] = 0;
    for (int d = 1; d <= 128; d++) dstart[d+1] = dstart[d] + dcnt[d];
    bucket = (int *)malloc(sizeof(int) * (size_t)(ninternal > 0 ? ninternal : 1));
    if (!bucket) goto done;
    {
        int *fillp = (int *)malloc(sizeof(int) * 129);
        if (!fillp) goto done;
        for (int d = 0; d <= 128; d++) fillp[d] = dstart[d];
        for (int v = 1; v < cnt; v++)
            if (ch[2*(size_t)v] >= 0 || ch[2*(size_t)v+1] >= 0)
                bucket[fillp[dep[v]]++] = v;
        free(fillp);
    }

    /* ---- U(b,e) for every admissible pair ---- */
    g = (u64 *)malloc(sizeof(u64) * 128 * 129);
    if (!g) goto done;
    memset(g, 0, sizeof(u64) * 128 * 129);

    size_t maxk = (size_t)(ninternal > 0 ? ninternal : 1) + 1;
    R = (u64 *)malloc(sizeof(u64) * maxk);
    ec = (u64 *)malloc(sizeof(u64) * maxk);
    fnode = (int *)malloc(sizeof(int) * (size_t)(cnt > 0 ? cnt : 1));
    fv = (int *)malloc(sizeof(int) * (size_t)(cnt > 0 ? cnt : 1));
    nnode = (int *)malloc(sizeof(int) * (size_t)(cnt > 0 ? cnt : 1));
    nfv = (int *)malloc(sizeof(int) * (size_t)(cnt > 0 ? cnt : 1));
    if (!R || !ec || !fnode || !fv || !nnode || !nfv) goto done;

    for (int b = 0; b < 128; b++) {
        int maxe = b + stride;
        if (maxe > 128) maxe = 128;
        int k;
        if (b == 0) {
            k = 1;
            fnode[0] = 0;
            fv[0] = 0;
            R[0] = mk[0] ? 32ULL : 0ULL;   /* the /0 rule stored in the root */
        } else {
            k = dcnt[b];
            const int *Lb = bucket + dstart[b];
            for (int i = 0; i < k; i++) { fnode[i] = Lb[i]; fv[i] = i; R[i] = 0; }
        }
        int fsize = k;
        for (int e = b + 1; e <= maxe; e++) {
            u64 delta = 32 + align8((u64)(e - b));   /* per rule of length e */
            u64 ce = delta;                          /* per edge to depth e */
            for (int i = 0; i < k; i++) ec[i] = 0;
            int nsize = 0;
            for (int t = 0; t < fsize; t++) {
                int w = fnode[t], vi = fv[t];
                int c0 = ch[2*(size_t)w];
                if (c0 >= 0) {
                    if (mk[c0]) R[vi] += delta;
                    if (ch[2*(size_t)c0] >= 0 || ch[2*(size_t)c0+1] >= 0) {
                        nnode[nsize] = c0; nfv[nsize] = vi;
                        ec[vi]++; nsize++;
                    }
                }
                int c1 = ch[2*(size_t)w + 1];
                if (c1 >= 0) {
                    if (mk[c1]) R[vi] += delta;
                    if (ch[2*(size_t)c1] >= 0 || ch[2*(size_t)c1+1] >= 0) {
                        nnode[nsize] = c1; nfv[nsize] = vi;
                        ec[vi]++; nsize++;
                    }
                }
            }
            u64 U = 0;
            for (int i = 0; i < k; i++)
                U += align64(128 + R[i] + ec[i] * ce);
            g[(size_t)b * 129 + e] = U;
            { int *tp = fnode; fnode = nnode; nnode = tp; }
            { int *tp = fv; fv = nfv; nfv = tp; }
            fsize = nsize;
        }
    }

    /* ---- exact DP over cut vectors ---- */
    size_t dp = (size_t)S * 129;
    bnum = (u64 *)malloc(sizeof(u64) * dp);
    bden = (u64 *)malloc(sizeof(u64) * dp);
    par = (int *)malloc(sizeof(int) * dp);
    if (!bnum || !bden || !par) goto done;
    for (size_t i = 0; i < dp; i++) { bnum[i] = INF; bden[i] = 1; par[i] = -1; }
    for (int d = 1; d <= 128 && d <= stride; d++) {
        u64 u = g[(size_t)d];
        if (u <= caps[0]) { bnum[d] = u; bden[d] = caps[0]; par[d] = 0; }
    }
    for (int s = 1; s < S; s++) {
        const u64 *pnum = bnum + (size_t)(s-1) * 129;
        const u64 *pden = bden + (size_t)(s-1) * 129;
        u64 *cnum = bnum + (size_t)s * 129;
        u64 *cden = bden + (size_t)s * 129;
        int *cpar = par + (size_t)s * 129;
        u64 cap = caps[s];
        for (int d = 1; d <= 128; d++) {
            int plo = d - stride;
            if (plo < 0) plo = 0;
            u64 best = INF, bestden = 1;
            int bestp = -1;
            for (int p = plo; p < d; p++) {
                u64 pn = pnum[p];
                if (pn == INF) continue;
                u64 u = g[(size_t)p * 129 + d];
                if (u > cap) continue;
                /* candidate = max(pn/pden[p], u/cap) */
                u64 n2, d2;
                if ((u128)u * pden[p] > (u128)pn * cap) { n2 = u; d2 = cap; }
                else { n2 = pn; d2 = pden[p]; }
                if (best == INF || (u128)n2 * bestden < (u128)best * d2) {
                    best = n2; bestden = d2; bestp = p;
                }
            }
            cnum[d] = best; cden[d] = bestden; cpar[d] = bestp;
        }
    }
    if (bnum[(size_t)(S-1) * 129 + 128] == INF) { rc = 0; goto done; }
    out_cuts[S] = 128;
    {
        int d = 128;
        for (int s = S - 1; s >= 1; s--) {
            d = par[(size_t)s * 129 + d];
            out_cuts[s] = d;
        }
        out_cuts[0] = 0;
    }
    rc = 1;

done:
    free(ch); free(mk); free(dep); free(dcnt); free(dstart); free(bucket);
    free(g); free(R); free(ec); free(fnode); free(fv); free(nnode); free(nfv);
    free(bnum); free(bden); free(par);
    return rc;
}
EOF
gcc -O2 -Wall -Wextra -c /app/submit/core.c -o /tmp/core.o && echo "core.c compiles cleanly"
